//! Gold: `l0` is 1:1 with the live `harness/electronics/l0.py`.
//!
//! `tests/fixtures/gold/l0_v1.json` was generated by `scripts/gold_l0.py` —
//! `record` cases feed a mock document (TOC + per-page text, image counts,
//! drawing counts) through `l0_record`, kernel cases call the pure readers.
//! The images/drawings layer is PDF-layer: per-page counts travel in the gold
//! exactly as the reference measures them (a raised `get_drawings` is
//! captured as `drawings: null` and degrades to 0).
//!
//! The cases pin the traps the substrate exists for: extension classes beat
//! every content rule (a zip printing "data sheet" is a container; `.bin` is
//! deliberately unclassifiable and the manifest prior fills the `unknown`),
//! class rules first-match in order, an unmapped prior leaves `unknown`,
//! deduplicated TOC sections carry lane counts, `toc_sections` counts every
//! section while `sections` caps at 400, and the text-poor buckets
//! (`needs_ocr` for near-blank pages with figures, `vision_candidate` for
//! thin pages with 2+ figures) plus `avg_page_chars`/`text_quality`
//! thresholds.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_recon::l0::{classify_document, extension_class, l0_record, PageFacts};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/l0_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

fn page_facts(spec: &Value) -> PageFacts {
    PageFacts {
        text: spec
            .get("text")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        images: spec.get("images").and_then(Value::as_u64).unwrap_or(0) as usize,
        drawings: if spec
            .get("drawings_error")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            None
        } else {
            Some(spec.get("drawings").and_then(Value::as_u64).unwrap_or(0) as usize)
        },
    }
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match case["kind"].as_str().unwrap() {
            "record" => {
                let input = &case["input"];
                let pages: Vec<PageFacts> = input["pages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(page_facts)
                    .collect();
                let toc: Vec<Value> = input["toc"].as_array().unwrap().clone();
                let got = l0_record(
                    &pages,
                    &toc,
                    input["source_path"].as_str().unwrap(),
                    input["manifest_prior"].as_str(),
                );
                assert_eq!(got, case["expected"], "case {name}");
            }
            "extension_class" => {
                let got = extension_class(case["input"]["filename"].as_str().unwrap());
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            "classify_document" => {
                let got = classify_document(
                    case["input"]["front_text"].as_str().unwrap(),
                    case["input"]["filename"].as_str().unwrap(),
                    case["input"]["toc_titles"].as_str().unwrap(),
                );
                assert_eq!(
                    serde_json::to_value(got).unwrap(),
                    case["expected"],
                    "case {name}"
                );
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
